import { Link } from 'react-router'
import { NoteActions } from './NoteActions.js'
import type { VaultTree } from '../../api/notes.js'

interface FileTreeProps {
  vaultId: string
  tree: VaultTree
  canEdit: boolean
}

export function FileTree({ vaultId, tree, canEdit }: FileTreeProps) {
  return (
    <nav>
      {Object.entries(tree).map(([type, notes]) => (
        <div key={type} className="mb-4">
          <div className="mb-1 text-xs uppercase tracking-wide text-muted-foreground">{type}</div>
          {notes.map((note) => (
            <div key={note.id} className="flex items-center justify-between gap-1">
              <Link
                to={`/vaults/${vaultId}/notes/${note.path}`}
                className="min-w-0 flex-1 truncate rounded px-2 py-1 text-sm hover:bg-muted"
              >
                {note.name}
              </Link>
              {canEdit && <NoteActions vaultId={vaultId} note={note} />}
            </div>
          ))}
        </div>
      ))}
    </nav>
  )
}

import { describe, expect, it, vi } from 'vitest'
import { render } from '@testing-library/react'
import { useCodeMirrorEditor } from './useCodeMirrorEditor'

function Harness({
  doc,
  onChange,
  readOnly,
  wikilinkTargets,
  onWikilinkClick,
}: {
  doc: string
  onChange: (doc: string) => void
  readOnly?: boolean
  wikilinkTargets?: string[]
  onWikilinkClick?: (target: string) => void
}) {
  const ref = useCodeMirrorEditor({ doc, onChange, readOnly, wikilinkTargets, onWikilinkClick })
  return <div ref={ref} data-testid="editor-container" />
}

describe('useCodeMirrorEditor', () => {
  it('mounts CodeMirror with the initial document text', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} />)

    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-editor')).not.toBeNull()
    expect(container.querySelector('.cm-content')?.textContent).toBe('# Hello')
  })

  it('does not call onChange on mount', () => {
    const onChange = vi.fn()
    render(<Harness doc="# Hello" onChange={onChange} />)

    expect(onChange).not.toHaveBeenCalled()
  })

  it('is editable by default (contenteditable true)', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} />)

    const content = getByTestId('editor-container').querySelector('.cm-content')
    expect(content?.getAttribute('contenteditable')).toBe('true')
  })

  it('is non-editable when readOnly is set (contenteditable false)', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} readOnly />)

    const content = getByTestId('editor-container').querySelector('.cm-content')
    expect(content?.getAttribute('contenteditable')).toBe('false')
  })

  it('applies markdown styling classes (heading, strong, emphasis, code)', () => {
    const { getByTestId } = render(
      <Harness doc={'# Title\n\n**bold** and *italic* and `code`'} onChange={vi.fn()} />,
    )
    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-md-h1')).not.toBeNull()
    expect(container.querySelector('.cm-md-strong')).not.toBeNull()
    expect(container.querySelector('.cm-md-emphasis')).not.toBeNull()
    expect(container.querySelector('.cm-md-code')).not.toBeNull()
  })

  it('shows the heading marker when the cursor is on that line', () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    // Default selection is at offset 0 → line 1 is active → marker visible.
    const firstLine = document.querySelector('.cm-line')
    expect(firstLine?.textContent).toBe('# Heading')
  })

  it('hides the heading marker when the cursor is on another line', async () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Move the cursor to the end (the "body" line) — line 1 is no longer active.
    view.dispatch({ selection: { anchor: view.state.doc.length } })
    const firstLine = document.querySelector('.cm-line')
    expect(firstLine?.textContent).toBe('Heading')
  })

  it('hides inline emphasis/code markers on an inactive line', async () => {
    render(<Harness doc={'top\n\n**bold** and `code`'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Cursor on line 1 ("top"); the emphasis/code line is inactive.
    view.dispatch({ selection: { anchor: 0 } })
    const lines = document.querySelectorAll('.cm-line')
    const last = lines[lines.length - 1]
    expect(last?.textContent).toBe('bold and code')
  })

  it('reveals a hidden heading marker when the cursor moves back onto its line', async () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!

    // Off the heading line → hidden.
    view.dispatch({ selection: { anchor: view.state.doc.length } })
    expect(document.querySelector('.cm-line')?.textContent).toBe('Heading')

    // Back onto the heading line → revealed.
    view.dispatch({ selection: { anchor: 0 } })
    expect(document.querySelector('.cm-line')?.textContent).toBe('# Heading')
  })

  it('keeps fenced-code fences visible (does not blank the ``` lines)', async () => {
    render(<Harness doc={'intro\n\n```\ncode\n```'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Cursor on line 1; the fenced block is inactive — fences must NOT be hidden.
    view.dispatch({ selection: { anchor: 0 } })
    const text = document.querySelector('.cm-content')?.textContent ?? ''
    expect(text).toContain('```')
    expect(text).toContain('code')
  })

  it('mounts with wikilinkTargets set (autocomplete wired, editor intact)', () => {
    const { getByTestId } = render(
      <Harness doc={'body'} onChange={vi.fn()} wikilinkTargets={['people/jane']} />,
    )
    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-content')?.textContent).toBe('body')
  })

  it('decorates wikilinks when onWikilinkClick is provided', () => {
    const { getByTestId } = render(
      <Harness doc={'see [[people/jane]]'} onChange={vi.fn()} onWikilinkClick={vi.fn()} />,
    )
    expect(getByTestId('editor-container').querySelector('.cm-wikilink')).not.toBeNull()
  })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { render, screen, waitFor } from '@testing-library/react'
import { createMemoryRouter, Outlet, RouterProvider } from 'react-router'
import { mockJsonResponse } from '../../lib/api'
import type { Vault } from '../../api/vaults'
import { NoteView } from './NoteView'

const EDIT_VAULT: Vault = { id: 'v1', name: 'V1', ownerId: 'u1', mergeable: false, access: 'edit' }
const READ_VAULT: Vault = { id: 'v1', name: 'V1', ownerId: 'u1', mergeable: false, access: 'read' }

// No default: passing `undefined` must stay undefined (a value default would
// swallow it), so the unknown-access → read-only path can be tested for real.
function renderNote(initialPath: string, vault: Vault | undefined) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  const router = createMemoryRouter(
    [
      {
        path: '/vaults/:vaultId',
        element: <Outlet context={vault} />,
        children: [{ path: 'notes/*', element: <NoteView /> }],
      },
    ],
    { initialEntries: [initialPath] },
  )
  render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  )
}

function putCalls(fetchMock: ReturnType<typeof vi.fn>) {
  return fetchMock.mock.calls.filter(([, init]) => (init as RequestInit | undefined)?.method === 'PUT')
}

describe('NoteView', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
    vi.useRealTimers()
  })

  it('renders the frontmatter and an editable CodeMirror body (edit access)', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockImplementation((url: string) => {
        if (url.endsWith('/tree')) return Promise.resolve(mockJsonResponse(200, {}))
        return Promise.resolve(
          mockJsonResponse(200, {
            path: 'people/jane',
            frontmatter: { type: 'people', timestamp: '2026-01-01T00:00:00.000Z' },
            body: '# Jane\n\nNotes about Jane.',
            updatedAt: '2026-01-01',
          }),
        )
      }),
    )

    renderNote('/vaults/v1/notes/people/jane', EDIT_VAULT)

    await waitFor(() => expect(screen.getByText('people')).toBeInTheDocument())
    // property panel is present (type shown read-only, resource field editable)
    expect(screen.getByText('resource')).toBeInTheDocument()
    const content = document.querySelector('.cm-content')
    expect(content).not.toBeNull()
    expect(content!.textContent).toContain('# Jane')
    expect(content!.textContent).toContain('Notes about Jane.')
    expect(content!.getAttribute('contenteditable')).toBe('true')
  })

  it('debounce-saves an edit to PUT /api/vaults/:id/notes/:path (edit access)', async () => {
    vi.useFakeTimers({ shouldAdvanceTime: true })
    const fetchMock = vi.fn().mockImplementation((url: string, init?: RequestInit) => {
      if (init?.method === 'PUT')
        return Promise.resolve(mockJsonResponse(200, { id: 'n1', path: 'people/jane', frontmatter: {}, body: 'edited', updatedAt: '2026-01-02' }))
      if (url.endsWith('/tree')) return Promise.resolve(mockJsonResponse(200, {}))
      return Promise.resolve(
        mockJsonResponse(200, { path: 'people/jane', frontmatter: {}, body: 'original', updatedAt: '2026-01-01' }),
      )
    })
    vi.stubGlobal('fetch', fetchMock)

    renderNote('/vaults/v1/notes/people/jane', EDIT_VAULT)
    await waitFor(() => expect(document.querySelector('.cm-content')).not.toBeNull())

    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: 'edited' } })

    await vi.advanceTimersByTimeAsync(800)
    expect(putCalls(fetchMock)).toHaveLength(0)

    await vi.advanceTimersByTimeAsync(700)
    await waitFor(() => expect(putCalls(fetchMock)).toHaveLength(1))
    expect(fetchMock).toHaveBeenCalledWith(
      '/api/vaults/v1/notes/people/jane',
      expect.objectContaining({ method: 'PUT', body: JSON.stringify({ body: 'edited' }) }),
    )
  })

  it('read-only access: editor is non-editable and never saves', async () => {
    vi.useFakeTimers({ shouldAdvanceTime: true })
    const fetchMock = vi.fn().mockImplementation((url: string, init?: RequestInit) => {
      if (init?.method === 'PUT') return Promise.resolve(mockJsonResponse(200, {}))
      if (url.endsWith('/tree')) return Promise.resolve(mockJsonResponse(200, {}))
      return Promise.resolve(
        mockJsonResponse(200, { path: 'people/jane', frontmatter: { type: 'people' }, body: 'original', updatedAt: '2026-01-01' }),
      )
    })
    vi.stubGlobal('fetch', fetchMock)

    renderNote('/vaults/v1/notes/people/jane', READ_VAULT)
    await waitFor(() => expect(document.querySelector('.cm-content')).not.toBeNull())

    expect(document.querySelector('.cm-content')!.getAttribute('contenteditable')).toBe('false')
    expect(screen.getByText(/read-only/i)).toBeInTheDocument()

    // Even a programmatic change (readOnly does not block dispatch) must not save.
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: 'hacked' } })
    await vi.advanceTimersByTimeAsync(2000)
    expect(putCalls(fetchMock)).toHaveLength(0)
  })

  it('locks the editor when vault access is unknown (undefined)', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockImplementation((url: string) => {
        if (url.endsWith('/tree')) return Promise.resolve(mockJsonResponse(200, {}))
        return Promise.resolve(
          mockJsonResponse(200, { path: 'people/jane', frontmatter: { type: 'people' }, body: 'original', updatedAt: '2026-01-01' }),
        )
      }),
    )

    // No vault in outlet context → access unknown → conservative read-only lock.
    renderNote('/vaults/v1/notes/people/jane', undefined)
    await waitFor(() => expect(document.querySelector('.cm-content')).not.toBeNull())

    expect(document.querySelector('.cm-content')!.getAttribute('contenteditable')).toBe('false')
    expect(screen.getByText(/read-only/i)).toBeInTheDocument()
  })

  it('shows a not-found message for a missing note', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(mockJsonResponse(404, { error: 'note not found' })))

    renderNote('/vaults/v1/notes/people/ghost', EDIT_VAULT)

    await waitFor(() => expect(screen.getByText('Note not found.')).toBeInTheDocument())
  })
})
